function renderHome(v){
  const items=[['exams','Bài kiểm tra'],['students','Học sinh & Lớp học'],['downloads','Tải phiếu chấm'],['settings','Cài đặt'],['account','Tài khoản'],['help','Trợ giúp & Hướng dẫn']];
  v.innerHTML='<div class="home-backdrop" aria-hidden="true"></div><section class="grade-menu" aria-label="Menu chính"><h1 class="visually-hidden">StarGrade — Menu chính</h1>'+items.map(([key,label])=>`<button class="grade-menu-button" data-home="${key}"><span class="grade-menu-icon">${menuIcon(key)}</span><span>${label}</span></button>`).join('')+'</section><p class="home-exam-status"></p>';
  v.querySelector('.home-exam-status').textContent=state.exam?'Bài đang chọn: '+state.exam.name:'Chọn Bài kiểm tra để tạo hoặc mở bài thi.';
  v.querySelectorAll('[data-home]').forEach(button=>button.onclick=()=>{const target=button.dataset.home,requiresExam=['students'].includes(target);state.tab=requiresExam&&!state.exam?'exams':target;render();if(requiresExam&&!state.exam)toast('Hãy tạo hoặc mở bài kiểm tra trước.')});
}
function renderHelp(v){
  v.innerHTML=`<section class="card help-card"><p class="help-eyebrow">STARGRADE</p><h1>Trợ giúp & Hướng dẫn</h1><p>Tạo bài kiểm tra, lưu đáp án, sau đó chụp phiếu để chấm và đối chiếu kết quả.</p>
    <details open><summary>1. Tạo bài kiểm tra</summary><p>Vào Bài kiểm tra, chọn đúng mẫu phiếu giấy, nhập tên bài và mã đề. Điều chỉnh số câu, điểm từng phần rồi bấm Tạo bài thi.</p></details>
    <details><summary>2. Nhập và lưu đáp án</summary><p><a class="btn" href="/assets/mau-nhap-dap-an.xlsx" download>Tải file Excel mẫu nhập đáp án</a></p><p>File mẫu gồm đáp án minh họa cho bốn mã đề. Giữ hàng tiêu đề, thay mã đề và đáp án bằng dữ liệu của bạn; mã đề cần khớp với bài thi. Phần I điền A/B/C/D, Phần II điền Đ/S từng ý, Phần III giữ dấu âm và dấu phẩy. Để trống các câu không dùng. Nhập Excel bằng nút biểu tượng Excel trong mục Đáp án, kiểm tra bản xem trước rồi xác nhận nhập.</p><p>Vào từng bài thi, mở Đáp án và chọn mã đề cần nhập. Bấm ô A/B/C/D, Đ/S hoặc nhập câu trả lời ngắn. Có thể dán chuỗi đáp án Phần I hoặc tải phiếu đã tô. Kiểm tra rồi bấm Lưu toàn bộ đáp án cho mỗi mã đề.</p></details>
    <details><summary>3. Nhập học sinh và lớp học</summary><p>Dán danh sách CSV trong Danh sách lớp với dòng đầu: SBD,Họ tên,Lớp. Giữ các số 0 ở đầu SBD. Nếu không ghép được tên, kết quả hiển thị ảnh vùng họ tên hoặc số phách trên phiếu.</p></details>
    <details><summary>4. Chụp và chấm phiếu</summary><p>Mở Chấm phiếu, chọn Chụp bằng camera hoặc Tải ảnh có sẵn. Đặt phiếu phẳng, đủ sáng, giữ rõ bốn mốc đen. Kiểm tra và sửa SBD, mã đề, đáp án nhận dạng trước khi bấm Chấm và lưu.</p><p>Camera cần địa chỉ HTTPS hợp lệ và quyền truy cập camera. Nếu chụp không được, mở bằng Chrome hoặc Safari.</p></details>
    <details><summary>5. Xem lại kết quả</summary><p>Trong Kết quả, chọn Xem phiếu làm bài. Vòng xanh lá là đáp án đúng, vòng đỏ là đáp án sai, vòng vàng chỉ đáp án đúng để đối chiếu. Kiểm tra các cảnh báo trước khi xuất CSV.</p></details>
    <details><summary>6. Điểm số và cập nhật đáp án</summary><p>Mặc định: Phần I 0,25 điểm/câu; Phần II đúng 1/2/3/4 ý được 0,1/0,25/0,5/1 điểm; Phần III 0,5 điểm/câu. Có thể đổi mức điểm khi tạo hoặc sửa bài thi. Sau khi sửa và lưu đáp án, các phiếu đã chấm của bài đó được tính lại điểm.</p><p>Phần III cần giữ đúng dấu âm, dấu phẩy và cách viết so với đáp án. Khi sửa bài thi, mẫu phiếu được giữ cố định.</p></details>
    <div class="actions"><button class="btn primary" id="helpExams">Mở Bài kiểm tra</button><button class="btn" id="helpDownloads">Tải phiếu chấm</button></div></section>`;
  $('#helpExams').onclick=()=>{state.tab='exams';render()};$('#helpDownloads').onclick=()=>{state.tab='downloads';render()};
}
function renderView(){const v=$('#view');if(state.tab==='home')return renderHome(v);if(state.tab==='downloads')return renderDownloads(v);if(state.tab==='help')return renderHelp(v);if(state.tab==='settings')return renderGradingSettings(v);if(state.tab==='account')return renderAccount(v);if(!state.exam&&state.tab!=='exams'){state.tab='home';return render()}if(state.tab==='exams')return renderExams(v);if(state.tab==='exam-menu')return renderExamDashboard(v);if(state.tab==='exam-stats')return renderExamStatistics(v);if(state.tab==='exam-info')return renderExamInfo(v);if(state.tab==='keys')return renderKeys(v);if(state.tab==='students')return renderStudents(v);if(state.tab==='results')return renderResults(v);return renderScan(v)}
function renderExamsBase(v){const point=e=>e?.part2_points||[.1,.25,.5,1];v.innerHTML=`<div class="card"><h2>Tạo bài thi</h2><div class="grid"><div><label>Tên bài</label><input id="examName" placeholder="Ví dụ: Toán 12 - Giữa kỳ"></div><div><label>Môn</label><input id="subject" value="Trắc nghiệm"></div><div><label>Mã đề 4 số, cách nhau bằng dấu phẩy</label><input id="codes" inputmode="numeric" value="0101,0102,0103,0104" placeholder="0101,0102,0103,0104"></div></div><h3>Cách tính điểm</h3><div class="score-settings"><fieldset><legend>Phần I</legend><label>Số câu<input id="count1" type="number" min="1" max="40" value="40"></label><label>Điểm một câu<input id="part1Point" type="number" min="0" max="100" step="0.01" value="0.25"></label></fieldset><fieldset><legend>Phần II</legend><label>Số câu<input id="count2" type="number" min="0" max="8" value="8"></label><label>Đúng 1 ý<input id="part2Point1" type="number" min="0" max="100" step="0.01" value="0.1"></label><label>Đúng 2 ý<input id="part2Point2" type="number" min="0" max="100" step="0.01" value="0.25"></label><label>Đúng 3 ý<input id="part2Point3" type="number" min="0" max="100" step="0.01" value="0.5"></label><label>Đúng 4 ý<input id="part2Point4" type="number" min="0" max="100" step="0.01" value="1"></label></fieldset><fieldset><legend>Phần III</legend><label>Số câu<input id="count3" type="number" min="0" max="6" value="6"></label><label>Điểm một câu<input id="part3Point" type="number" min="0" max="100" step="0.01" value="0.5"></label></fieldset></div><button class="btn primary" id="createExam">Tạo bài thi</button></div><div class="card"><h2>Bài thi đã tạo</h2>${state.exams.map(e=>`<div class="row"><span><b>${e.name}</b><br><small>${e.subject} · I: ${e.question_count} câu × ${e.part1_point??.25} · II: ${e.part2_count??8} câu (${point(e).join(' / ')}) · III: ${e.part3_count??6} câu × ${e.part3_point??.5}</small></span><span class="actions"><button class="btn" data-select="${e.id}">Mở</button><button class="btn danger-btn" data-delete="${e.id}">Xóa</button></span></div>`).join('')||'<p class="muted">Chưa có bài thi.</p>'}</div>`;$('#createExam').onclick=async()=>{try{const d=await api('/exams',{method:'POST',body:JSON.stringify({sheet_template:$('#sheetTemplate').value,name:$('#examName').value,subject:$('#subject').value,question_count:$('#count1').value,part2_count:$('#count2').value,part3_count:$('#count3').value,part1_point:$('#part1Point').value,part2_point_1:$('#part2Point1').value,part2_point_2:$('#part2Point2').value,part2_point_3:$('#part2Point3').value,part2_point_4:$('#part2Point4').value,part3_point:$('#part3Point').value,codes:$('#codes').value.split(',')})});await loadExams();await selectExam(d.id);state.tab='keys';render();toast('Đã tạo bài thi')}catch(e){toast(e.message)}};document.querySelectorAll('[data-select]').forEach(b=>b.onclick=async()=>{await selectExam(b.dataset.select);state.tab='scan';render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{const exam=state.exams.find(e=>e.id===Number(b.dataset.delete));if(!confirm(`Xóa bài thi “${exam?.name||''}” cùng toàn bộ đáp án và kết quả?`))return;try{await api('/exams/'+b.dataset.delete,{method:'DELETE'});state.exam=null;await loadExams();render();toast('Đã xóa bài thi')}catch(e){toast(e.message)}})}
function part1Count(){return Math.max(1,Math.min(activeSheetTemplate().p1.length,Number(state.exam.question_count)||40))}
function part2Count(){return Math.max(0,Math.min(activeSheetTemplate().p2.length/4,Number(state.exam.part2_count??8)))}
function part3Count(){return Math.max(0,Math.min(activeSheetTemplate().p3.length,Number(state.exam.part3_count??6)))}
function keyRows(){return Array.from({length:part1Count()},(_,i)=>`<div class="answer-question"><b>${i+1}</b><div class="answer-dots">${['A','B','C','D'].map(x=>`<button type="button" class="answer-dot" data-q="${i}" data-answer="${x}" aria-label="Câu ${i+1}: ${x}">${x}</button>`).join('')}</div></div>`).join('')}
function setPart1Answers(answers){for(let i=0;i<part1Count();i++){const value=answers[i]||'-';document.querySelectorAll(`[data-q="${i}"]`).forEach(b=>b.classList.toggle('selected',b.dataset.answer===value))}}
function getPart1Answers(){return Array.from({length:part1Count()},(_,i)=>document.querySelector(`[data-q="${i}"].selected`)?.dataset.answer||'-').join('')}
function bindPart1Dots(){document.querySelectorAll('.answer-dot').forEach(b=>b.onclick=()=>{document.querySelectorAll(`[data-q="${b.dataset.q}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')})}
function setPart2Answers(answers){for(let q=0;q<part2Count();q++)for(let row=0;row<4;row++){const value=(answers[q]||'----')[row]||'-';document.querySelectorAll(`[data-p2="${q}-${row}"]`).forEach(b=>b.classList.toggle('selected',b.dataset.answer===value))}}
function getPart2Answers(){return Array.from({length:part2Count()},(_,q)=>Array.from({length:4},(_,row)=>document.querySelector(`[data-p2="${q}-${row}"].selected`)?.dataset.answer||'-').join(''))}
function bindPart2Dots(){document.querySelectorAll('.part2-dot').forEach(b=>b.onclick=()=>{const group=`[data-p2="${b.dataset.p2}"]`;if(b.classList.contains('selected'))b.classList.remove('selected');else{document.querySelectorAll(group).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')}})}
function reviewRing(x,y,color){return `<circle class="review-ring ${color}" cx="${x}" cy="${y}" r="11"/>`}
function digitReviewMarks(value,xs){const ys=[219,265,311,357,406,451,497,543,588,634];return String(value||'').split('').map((digit,i)=>/^\d$/.test(digit)&&xs[i]!=null?reviewRing(xs[i],ys[Number(digit)],'correct'):'').join('')}
function cropCandidateNameVertical(dataUrl){return new Promise(resolve=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),sx=img.naturalWidth/1552,sy=img.naturalHeight/2254;c.width=Math.round(350*sx);c.height=Math.round(70*sy);const ctx=c.getContext('2d');ctx.drawImage(img,650*sx,435*sy,350*sx,70*sy,0,0,c.width,c.height);resolve(c.toDataURL('image/png'))};img.onerror=()=>resolve(null);img.src=dataUrl})}
function part3ReviewMarks(value,base,color){let marks='',column=0;for(const char of String(value||'')){if(char==='-'){marks+=reviewRing(base+column*45,1674,color);column++;continue}if(char===','){marks+=reviewRing(base+column*45,1706,color);column++;continue}const digit=Number(char);if(Number.isInteger(digit)&&digit>=0&&digit<=9&&column<4)marks+=reviewRing(base+column*45,1746+digit*36,color);column++}return marks}
function reviewMarks(row,key){if(!key)return '';let marks=digitReviewMarks(row.student_no,[1064,1094,1124,1157,1187,1223,1250,1283])+digitReviewMarks(row.code,[1355,1392,1428,1465]);const cols=[179,247,315,383],offs=[0,341,682,1023];for(let i=0;i<Math.min(40,(row.answers||'').length,(key.answers||'').length);i++){const given=row.answers[i],correct=key.answers[i],x=cols['ABCD'.indexOf(given)]+offs[Math.floor(i/10)],y=853+(i%10)*36;if(!'ABCD'.includes(given)||!'ABCD'.includes(correct))continue;if(given===correct)marks+=reviewRing(x,y,'correct');else{marks+=reviewRing(x,y,'wrong');marks+=reviewRing(cols['ABCD'.indexOf(correct)]+offs[Math.floor(i/10)],y,'expected')}}const p2x=[[178,247],[316,384],[519,587],[657,725],[859,927],[997,1065],[1199,1267],[1337,1405]];(key.part2||[]).forEach((correct,q)=>{const given=(row.part2||[])[q]||'';for(let r=0;r<4;r++){const a=given[r],b=correct[r],y=1367+r*35;if(!'ĐS'.includes(a)||!'ĐS'.includes(b))continue;if(a===b)marks+=reviewRing(p2x[q][a==='Đ'?0:1],y,'correct');else{marks+=reviewRing(p2x[q][a==='Đ'?0:1],y,'wrong');marks+=reviewRing(p2x[q][b==='Đ'?0:1],y,'expected')}}});[169,386,603,820,1037,1254].forEach((base,i)=>{const given=(row.part3||[])[i]||'',correct=(key.part3||[])[i]||'';if(!given||!correct)return;marks+=part3ReviewMarks(given,base,given===correct?'correct':'wrong');if(given!==correct)marks+=part3ReviewMarks(correct,base,'expected')});return marks}
function renderKeys(v){const key=state.exam.keys[0]?.answers||'-'.repeat(state.exam.question_count);v.innerHTML=`<div class="card"><h2>Đáp án · ${state.exam.name}</h2><p class="muted">Nhập đáp án cho mã đề đang chọn.</p><select id="keyCode">${state.exam.codes.map(c=>`<option>${c}</option>`).join('')}</select><div class="grid">${keyRows()}</div><button class="btn primary" id="saveKey">Lưu đáp án</button></div>`;[...document.querySelectorAll('[data-q]')].forEach((s,i)=>s.value=key[i]||'-');$('#saveKey').onclick=async()=>{const answers=[...document.querySelectorAll('[data-q]')].map(s=>s.value).join('');await api('/exams/'+state.exam.id+'/keys',{method:'PUT',body:JSON.stringify({keys:[{code:$('#keyCode').value,answers}]})});await selectExam(state.exam.id);toast('Đã lưu đáp án')}}
