function recognizeSheet(file){
  return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),ctx=c.getContext('2d');c.width=img.naturalWidth;c.height=img.naturalHeight;ctx.drawImage(img,0,0);const sx=c.width/1552,sy=c.height/2254,score=(x,y)=>{let d=0,n=0;for(let yy=Math.round(y*sy)-7;yy<=Math.round(y*sy)+7;yy++)for(let xx=Math.round(x*sx)-7;xx<=Math.round(x*sx)+7;xx++){const p=ctx.getImageData(Math.max(0,xx),Math.max(0,yy),1,1).data;if((p[0]+p[1]+p[2])/3<125)d++;n++}return d/n},pick=(xs,y,labels)=>{const a=xs.map(x=>score(x,y)),m=Math.max(...a);return m<.22?'-':labels[a.indexOf(m)]},readDigits=xs=>xs.map(x=>{let m=0,v='?';[219,265,311,357,406,451,497,543,588,634].forEach((y,i)=>{const s=score(x,y);if(s>m){m=s;v=String(i)}});return m<.22?'?':v}).join('');const student_no=readDigits([1064,1094,1124,1157,1187,1223,1250,1283]),code=readDigits([1355,1392,1428,1465]),cols=[179,247,315,383],offs=[0,341,682,1023];let part1='';for(let q=0;q<40;q++)part1+=pick(cols.map(x=>x+offs[Math.floor(q/10)]),853+(q%10)*36,['A','B','C','D']);const p2x=[[178,247],[316,384],[519,587],[657,725],[859,927],[997,1065],[1199,1267],[1337,1405]],part2=p2x.map(xs=>[0,1,2,3].map(r=>pick(xs,1367+r*35,['Đ','S'])).join('')),part3=[];[169,386,603,820,1037,1254].forEach(base=>{const digits=[];for(let col=0;col<4;col++){let m=0,v='?';for(let r=0;r<10;r++){const s=score(base+[0,45,91,137][col],1746+r*36);if(s>m){m=s;v=String(r)}}digits.push(m<.22?'?':v)}part3.push({negative:score(base,1674)>=.22,comma:score(base+45,1706)>=.22,digits:digits.join('')})});resolve({student_no,code,part1,part2,part3,calibrated:false})};img.onerror=reject;img.src=URL.createObjectURL(file)})
}

