function recognizeSheetCalibrated(file){
  return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),ctx=c.getContext('2d');c.width=img.naturalWidth;c.height=img.naturalHeight;ctx.drawImage(img,0,0);const sx=c.width/1552,sy=c.height/2254;const findMarker=(ex,ey)=>{let sumX=0,sumY=0,n=0;const cx=ex*sx,cy=ey*sy;for(let y=Math.max(0,cy-75*sy);y<=Math.min(c.height,cy+75*sy);y+=2)for(let x=Math.max(0,cx-75*sx);x<=Math.min(c.width,cx+75*sx);x+=2){const p=ctx.getImageData(Math.round(x),Math.round(y),1,1).data;if((p[0]+p[1]+p[2])/3<45){sumX+=x;sumY+=y;n++}}return n?{x:sumX/n,y:sumY/n}:null};const marks=[findMarker(50,50),findMarker(1500,50),findMarker(50,2200),findMarker(1500,2200)];const mapPoint=(x,y)=>{if(marks.some(v=>!v))return{x:x*sx,y:y*sy};const t=x/1552,u=y/2254,top={x:marks[0].x+(marks[1].x-marks[0].x)*t,y:marks[0].y+(marks[1].y-marks[0].y)*t},bot={x:marks[2].x+(marks[3].x-marks[2].x)*t,y:marks[2].y+(marks[3].y-marks[2].y)*t};return{x:top.x+(bot.x-top.x)*u,y:top.y+(bot.y-top.y)*u}};const score=(x,y)=>{const p=mapPoint(x,y);let dark=0,total=0;for(let yy=Math.round(p.y)-7;yy<=Math.round(p.y)+7;yy++)for(let xx=Math.round(p.x)-7;xx<=Math.round(p.x)+7;xx++){const q=ctx.getImageData(Math.max(0,xx),Math.max(0,yy),1,1).data;if((q[0]+q[1]+q[2])/3<125)dark++;total++}return dark/total};const pick=(xs,y,labels)=>{const a=xs.map(x=>score(x,y)),m=Math.max(...a),i=a.indexOf(m);return m<.22?'-':labels[i]};const digitY=[219,265,311,357,406,451,497,543,588,634],readDigits=xs=>xs.map(x=>{let m=0,d='?';digitY.forEach((y,i)=>{const s=score(x,y);if(s>m){m=s;d=String(i)}});return m<.22?'?':d}).join('');const student_no=readDigits([1064,1094,1124,1157,1187,1223,1250,1283]),code=readDigits([1355,1392,1428,1465]);const cols=[179,247,315,383],offs=[0,341,682,1023];let part1='';for(let q=0;q<40;q++)part1+=pick(cols.map(x=>x+offs[Math.floor(q/10)]),853+(q%10)*36,['A','B','C','D']);const p2x=[[178,247],[316,384],[519,587],[657,725],[859,927],[997,1065],[1199,1267],[1337,1405]],part2=p2x.map(xs=>[0,1,2,3].map(r=>pick(xs,1367+r*35,['Đ','S'])).join(''));const p3=[];[169,386,603,820,1037,1254].forEach(base=>{const digits=[];for(let col=0;col<4;col++){let best=0,row='?';for(let r=0;r<10;r++){const s=score(base+[0,45,91,137][col],1746+r*36);if(s>best){best=s;row=String(r)}}digits.push(best<.22?'?':row)}p3.push({negative:score(base,1674)>=.22,comma:score(base+45,1706)>=.22,digits:digits.join('')})});resolve({student_no,code,part1,part2,part3:p3,calibrated:marks.every(Boolean)});};img.onerror=reject;img.src=URL.createObjectURL(file)})
}

