  $('#image').onchange=async e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=async()=>{state.image=r.result;$('#preview').src=r.result;$('#preview').classList.remove('hidden');try{const d=await recognizeSheet(f);const formatShort=x=>{let s=x.digits;if(x.comma){const pos=s.indexOf('?');s=pos>=0?s.slice(0,pos)+','+s.slice(pos+1):s.slice(0,1)+','+s.slice(1)}s=s.replace(/\?/g,'').replace(/^,+|,+$/g,'');return (x.negative?'-':'')+s};$('#studentNo').value=d.student_no;if(!state.exam.codes.includes(d.code))$('#code').insertAdjacentHTML('beforeend',`<option>${d.code}</option>`);$('#code').value=d.code;$('#answers').value=d.part1;$('#p2answers').value=d.part2.join(' | ');$('#p3answers').value=d.part3.map(formatShort).join(' | ');$('#omrReadout').innerHTML=`<b>Đã đọc tự động</b><br>SBD: ${d.student_no} · Mã đề: ${d.code}`;}catch(err){$('#omrReadout').textContent='Không nhận dạng được ảnh, hãy kiểm tra lại ảnh hoặc nhập thủ công.'}};r.readAsDataURL(f)};
  $('#submit').onclick=async()=>{try{const d=await api('/exams/'+state.exam.id+'/submissions',{method:'POST',body:JSON.stringify({student_no:$('#studentNo').value,student_name:$('#studentName').value,code:$('#code').value,answers:$('#answers').value.toUpperCase().replace(/[^ABCD?\-]/g,''),part2:$('#p2answers').value.toUpperCase().split('|').map(x=>x.trim().replace(/[^ĐS\-]/g,'')).filter(Boolean),part3:$('#p3answers').value.split('|').map(x=>x.trim()),image_data:state.image})});toast(`Đã chấm: ${d.score} điểm (I: ${d.parts.part1}; II: ${d.parts.part2}; III: ${d.parts.part3})`);state.tab='results';render()}catch(e){toast(e.message)}};$('#clear').onclick=()=>renderScan(v)
