  $('#cameraCapture').onclick=()=>{const video=$('#sheetCameraVideo'),guide=$('.camera-guide'),canvas=document.createElement('canvas'),vr=video.getBoundingClientRect(),gr=guide.getBoundingClientRect();if(!video.videoWidth||!video.videoHeight||!gr.width||!gr.height){toast('Camera chưa sẵn sàng, hãy thử lại');return}const scale=Math.min(vr.width/video.videoWidth,vr.height/video.videoHeight),drawW=video.videoWidth*scale,drawH=video.videoHeight*scale,offsetX=(vr.width-drawW)/2,offsetY=(vr.height-drawH)/2;let sx=(gr.left-vr.left-offsetX)/scale,sy=(gr.top-vr.top-offsetY)/scale,sw=gr.width/scale,sh=gr.height/scale;sx=Math.max(0,Math.min(video.videoWidth-1,sx));sy=Math.max(0,Math.min(video.videoHeight-1,sy));sw=Math.min(sw,video.videoWidth-sx);sh=Math.min(sh,video.videoHeight-sy);canvas.width=Math.round(sw);canvas.height=Math.round(sh);canvas.getContext('2d').drawImage(video,sx,sy,sw,sh,0,0,canvas.width,canvas.height);canvas.toBlob(async blob=>{if(!blob)return;closeSheetCamera();await fillFromSheetFile(new File([blob],'phieu-camera-a4.jpg',{type:'image/jpeg'}))},'image/jpeg',.96)};
  $('#submit').onclick=async()=>{try{const d=await api('/exams/'+state.exam.id+'/submissions',{method:'POST',body:JSON.stringify({student_no:$('#studentNo').value,student_name:$('#studentName').value,code:$('#code').value,answers:$('#answers').value.toUpperCase().replace(/[^ABCD?\-]/g,''),part2:$('#p2answers').value.toUpperCase().split('|').map(x=>x.trim().replace(/[^ĐS\-]/g,'')).filter(Boolean),part3:$('#p3answers').value.split('|').map(x=>x.trim()),image_data:state.image})});toast(`Đã chấm: ${d.score} điểm (I: ${d.parts.part1}; II: ${d.parts.part2}; III: ${d.parts.part3})`);state.tab='results';render()}catch(e){toast(e.message)}};
